fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let len = s.len();
    let mut result = Vec::with_capacity(len);

    // Process each complete block of 3 elements
    for chunk in s.chunks(3) {
        if chunk.len() == 3 {
            // (x0, x1, x2) -> (x1, x2, x0)
            result.push(chunk[1]);
            result.push(chunk[2]);
            result.push(chunk[0]);
        } else {
            // Any remaining elements fewer than 3 are copied as-is
            result.extend_from_slice(chunk);
        }
    }

    result
}

